using DadoRetail.Domain.Common;namespace DadoRetail.Domain.Partners;public sealed class Supplier:Entity{private Supplier(){}public Supplier(string name,string? taxId=null,string? phone=null){if(string.IsNullOrWhiteSpace(name))throw new ArgumentException(nameof(name));Name=name.Trim();TaxId=taxId?.Trim();Phone=phone?.Trim();}public string Name{get;private set;}=null!;public string? TaxId{get;private set;}public string? Phone{get;private set;}public bool IsActive{get;private set;}=true;}
